-- Script adaptado para PostgreSQL (Neon / Supabase / Render) equivalente a Veterinaria.sql + Usuarios.sql
-- Usa identificadores con comillas dobles para coincidir exactamente con VeterinariaContext de EF Core.

CREATE TABLE IF NOT EXISTS "Propietarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" varchar(100) NOT NULL CHECK (length(btrim("Nombre")) > 0),
    "Documento" varchar(8) NOT NULL UNIQUE CHECK (length("Documento") = 8 AND "Documento" ~ '^[0-9]{8}$'),
    "Telefono" varchar(15) NOT NULL
);

CREATE TABLE IF NOT EXISTS "Mascotas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" varchar(80) NOT NULL CHECK (length(btrim("Nombre")) > 0),
    "Especie" varchar(40) NOT NULL CHECK (length(btrim("Especie")) > 0),
    "Edad" integer NOT NULL CHECK ("Edad" BETWEEN 0 AND 50),
    "Peso" numeric(7,2) NOT NULL CHECK ("Peso" BETWEEN 0.01 AND 1000),
    "PropietarioId" integer NOT NULL REFERENCES "Propietarios"("Id")
);

CREATE INDEX IF NOT EXISTS "IX_Mascotas_PropietarioId" ON "Mascotas"("PropietarioId");

CREATE TABLE IF NOT EXISTS "Usuarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Correo" varchar(254) NOT NULL UNIQUE,
    "ClaveHash" varchar(100) NOT NULL,
    "Rol" varchar(30) NOT NULL CHECK ("Rol" IN ('Veterinario', 'Recepcionista'))
);

INSERT INTO "Propietarios" ("Nombre", "Documento", "Telefono")
SELECT v."Nombre", v."Documento", v."Telefono"
FROM (VALUES
    ('Ana Torres', '12345678', '987654321'),
    ('Luis Ramos', '87654321', '912345678'),
    ('Carla Flores', '45678912', '956123456')
) AS v("Nombre", "Documento", "Telefono")
WHERE NOT EXISTS (SELECT 1 FROM "Propietarios" p WHERE p."Documento" = v."Documento");

INSERT INTO "Mascotas" ("Nombre", "Especie", "Edad", "Peso", "PropietarioId")
SELECT v."Nombre", v."Especie", v."Edad", v."Peso", p."Id"
FROM (VALUES
    ('Luna', 'Perro', 3, 12.50, '12345678'),
    ('Milo', 'Gato', 2, 4.20, '12345678'),
    ('Rocky', 'Perro', 5, 22.80, '87654321')
) AS v("Nombre", "Especie", "Edad", "Peso", "Doc")
JOIN "Propietarios" p ON p."Documento" = v."Doc"
WHERE NOT EXISTS (SELECT 1 FROM "Mascotas" m WHERE m."Nombre" = v."Nombre" AND m."PropietarioId" = p."Id");

